    ow = tl.program_id(0)
    oh = tl.program_id(1)
    n = tl.program_id(2).to(tl.int64)
    ncol = 4320
    row = (n * Ho + oh) * Wo + ow
    for c0 in range(0, ncol, BLOCK):
        col = c0 + tl.arange(0, BLOCK)
        cm = col < ncol
        ch = col // 9
        tap = col % 9
        ih = oh * 2 - 1 + tap // 3
        iw = ow * 2 - 1 + tap % 3
        ok = cm & (ih >= 0) & (ih < H) & (iw >= 0) & (iw < W)
        v = tl.load(x + n * x_s0 + ch * x_s1 + ih * x_s2 + iw * x_s3, mask=ok, other=0)
        tl.store(out + row * ncol + col, v, mask=cm)
